    std::deque<Tuple> elastic_queue;
    uint64_t elastic_up=0,elastic_down=0,elastic_discard=0,inverse_input_model=0;
    uint64_t elastic_total_up=0,elastic_total_down=0,elastic_total_discard=0,elastic_fence_checks=0,elastic_hold_checks=0;
    bool elastic_fence_seen=false;
#if ELASTIC
    Tuple staged_tuple()const{const auto&r=*d.rootp;return {
        unsigned(r.cs88_pipeline_v91k__DOT__staged_plane),unsigned(r.cs88_pipeline_v91k__DOT__staged_block),
        unsigned(r.cs88_pipeline_v91k__DOT__staged_index),unsigned(r.cs88_pipeline_v91k__DOT__staged_tile),
        unsigned(r.cs88_pipeline_v91k__DOT__staged_qcell),unsigned(r.cs88_pipeline_v91k__DOT__staged_qscale),
        r.cs88_pipeline_v91k__DOT__staged_epoch,r.cs88_pipeline_v91k__DOT__staged_child_epoch,
        int(int16_t(r.cs88_pipeline_v91k__DOT__staged_value))};}
    void elastic_pre(){
        const auto&r=*d.rootp;
        const bool kill=d.reset||r.cs88_pipeline_v91k__DOT__accepted_start||r.cs88_pipeline_v91k__DOT__coefficient_stage_cancel;
        const bool full=r.cs88_pipeline_v91k__DOT__coefficient_boundary__DOT__full;
        const bool valid=r.cs88_pipeline_v91k__DOT__staged_valid,ready=r.cs88_pipeline_v91k__DOT__staged_ready;
        need(full==!elastic_queue.empty()&&elastic_queue.size()<=1,"independent staged occupancy/owner bound");
        need(bool(r.cs88_pipeline_v91k__DOT__coefficient_stage_occupied)==(full||bool(r.cs88_pipeline_v91k__DOT__coefficient_boundary__DOT__final_wait)),"stage occupied binding");
        if(d.reset||r.cs88_pipeline_v91k__DOT__accepted_start)inverse_input_model=0;
        if(kill){
            need(!valid&&!d.coefficient_ready&&!r.cs88_pipeline_v91k__DOT__staged_done,"stage flush leaked valid/ready/done");
            elastic_discard+=elastic_queue.size();elastic_total_discard+=elastic_queue.size();elastic_queue.clear();elastic_fence_seen=false;
        }else{
            need(bool(r.cs88_pipeline_v91k__DOT__staged_done)==(elastic_fence_seen&&elastic_queue.empty()),"registered done fence ordering");
            if(r.cs88_pipeline_v91k__DOT__staged_done){need(d.coefficient_done&&!valid&&!full,"done overtook raw completion/queued token");++elastic_fence_checks;}
            need(!r.cs88_pipeline_v91k__DOT__coefficient_boundary__DOT__final_wait,"real sticky producer done preceded its final acceptance");
            if(valid){need(!elastic_queue.empty()&&staged_tuple()==elastic_queue.front(),"full coefficient ownership tuple changed/reordered");if(!ready)++elastic_hold_checks;}
            if(valid&&ready){elastic_queue.pop_front();++elastic_down;++elastic_total_down;++inverse_input_model;}
            if(d.coefficient_valid&&d.coefficient_ready){elastic_queue.push_back(coefficient_tuple());++elastic_up;++elastic_total_up;}
            if(d.coefficient_done)elastic_fence_seen=true;
        }
        need(elastic_up==elastic_down+elastic_discard+elastic_queue.size(),"up/down/discard accepted-token conservation");
    }
    void elastic_post(){const auto&r=*d.rootp;
        need(bool(r.cs88_pipeline_v91k__DOT__coefficient_boundary__DOT__full)==!elastic_queue.empty(),"registered slot owner after edge");
        need(d.inverse_count_inputs==inverse_input_model,"independent inverse accepted staged input counter");}
#endif

